<!--
文件：web/src/modules/test-management/scope/TestScopePage.vue
说明：测试范围页面或交互组件。
用途：承载用户可见的加载、空、失败、提交和交互状态。
作者：hengguan
-->
<script setup lang="ts">
// 关键逻辑：页面只消费现有全局项目上下文；当前测试大类、项目和实体选择共同决定请求范围，前端显隐不替代服务端校验。
import { computed, onMounted, reactive, ref, watch } from 'vue'
import { Delete, Edit, Folder, FolderOpened, Plus, Refresh, Search, Setting, Upload, Box, CircleClose, CircleCheck } from '@element-plus/icons-vue'
import { ElMessage, ElMessageBox } from 'element-plus'
import { useRoute } from 'vue-router'
import UiDataTable from '../../../components/ui/UiDataTable.vue'
import UiEmptyState from '../../../components/ui/UiEmptyState.vue'
import UiPageHeader from '../../../components/ui/UiPageHeader.vue'
import TestManagementFormDialog from '../components/TestManagementFormDialog.vue'
import { useAuthStore } from '../../../stores/auth'
import { useProjectContextStore } from '../../../stores/project-context'
import { deleteTestScope, deleteTestScopeDirectory, downloadTestScopeFile, getTestScopeTree, importTestScopes, listTestDictionaries, listTestDictionaryOptions, listTestProjects, listTestScopes, previewTestScopeImport, restoreTestScope, saveTestScope, saveTestScopeDirectory, setTestScopeInvalidated, type TestDictionary, type TestDictionaryOption, type TestDirectory, type TestDomain, type TestManagementTree, type TestScope, type TestScopeImportPreview } from '../api'

type ScopeTreeNode = { key: string; type: 'project' | 'system' | 'directory'; id?: number; label: string; children?: ScopeTreeNode[]; directory?: TestDirectory }
type Column = { key: string; label: string; prop?: keyof TestScope; width?: number; minWidth?: number; visible: boolean }
const route = useRoute(); const auth = useAuthStore(); const context = useProjectContextStore()
const domain = computed(() => String(route.params.domain) as TestDomain)
const projects = ref<Array<{ id: number; project_code: string; project_name: string }>>([])
const projectId = computed(() => projects.value.find(item => item.project_code === context.currentRef)?.id)
const projectName = computed(() => projects.value.find(item => item.id === projectId.value)?.project_name || '当前项目')
const tree = ref<TestManagementTree>(); const rows = ref<TestScope[]>([]); const loading = ref(false); const total = ref(0); const page = ref(1)
const keyword = ref(''); const selectedSystem = ref<number>(); const selectedDirectory = ref<number>(); const recycled = ref(false)
const filters = reactive({ status: [] as string[], functionType: [] as string[], changeStatus: [] as string[], importance: [] as string[], accountingFlag: [] as string[], coverage: '' as '' | 'COVERED' | 'UNCOVERED' })
const sort = reactive({ prop: 'updated_at', order: 'descending' as 'ascending' | 'descending' })
const drawer = ref(false); const directoryDialog = ref(false); const columnsDialog = ref(false); const importDialog = ref(false); const saving = ref(false); const editing = ref<TestScope>(); const editingDirectory = ref<TestDirectory>(); const form = reactive<Partial<TestScope>>({}); const directory = reactive<Partial<TestDirectory>>({}); const importFile = ref<File>(); const importPreview = ref<TestScopeImportPreview>(); const duplicateAction = ref<'SKIP' | 'OVERWRITE'>('SKIP')
const dictionaries = ref<TestDictionary[]>([]); const options = reactive<Record<string, TestDictionaryOption[]>>({})
const allColumns: Column[] = [
  { key: 'scope_code', label: '序号', prop: 'scope_code', minWidth: 138, visible: true }, { key: 'scope_name', label: '功能/用例/批处理名称', prop: 'scope_name', minWidth: 180, visible: true },
  { key: 'leaf_menu', label: '末级菜单名称', prop: 'leaf_menu', minWidth: 150, visible: true }, { key: 'physical_system_name', label: '所属系统', prop: 'physical_system_name', minWidth: 120, visible: true },
  { key: 'directory_name', label: '所属目录', prop: 'directory_name', minWidth: 120, visible: true }, { key: 'function_type', label: '功能类型', prop: 'function_type', minWidth: 100, visible: false },
  { key: 'change_status', label: '变动状态', prop: 'change_status', minWidth: 90, visible: false }, { key: 'importance', label: '业务重要程度', prop: 'importance', minWidth: 110, visible: false },
  { key: 'accounting_flag', label: '是否核算相关', prop: 'accounting_flag', minWidth: 106, visible: false }, { key: 'status', label: '状态', prop: 'status', width: 92, visible: true },
  { key: 'case_count', label: '案例覆盖数', prop: 'case_count', minWidth: 96, visible: true }, { key: 'created_by_name', label: '创建人', prop: 'created_by_name', minWidth: 92, visible: false },
  { key: 'created_at', label: '创建时间', prop: 'created_at', minWidth: 132, visible: false }, { key: 'updated_by_name', label: '更新人', prop: 'updated_by_name', minWidth: 92, visible: true },
  { key: 'updated_at', label: '更新时间', prop: 'updated_at', minWidth: 132, visible: true }
]
const columns = ref<Column[]>(allColumns.map(item => ({ ...item })))
const can = (action?: string) => auth.hasPermission('test-management:' + domain.value + ':scope' + (action ? ':' + action : ''))
const systems = computed(() => tree.value?.systems || []); const directories = computed(() => tree.value?.directories || [])
const formSystemName = computed(() => { const item = systems.value.find(system => system.id === form.physical_subsystem_id); return item ? (item.short_name || item.name) : '-' })
const columnKey = computed(() => 'tm-scope-columns:' + (auth.user?.id || 'anonymous') + ':' + domain.value + ':' + (projectId.value || 0))
const selectedTreeKey = computed(() => selectedDirectory.value ? 'directory:' + selectedDirectory.value : selectedSystem.value ? 'system:' + selectedSystem.value : 'project')
const activeColumns = computed(() => columns.value.filter(item => item.visible))
const dictionaryOptions = (code: string) => options[code] || []
function directoryChildren(systemId: number, parentId?: number): ScopeTreeNode[] { return directories.value.filter(item => item.physical_subsystem_id === systemId && (item.parent_id || undefined) === parentId).map(item => ({ key: 'directory:' + item.id, type: 'directory', id: item.id, label: item.directory_name, directory: item, children: directoryChildren(systemId, item.id) })) }
const treeData = computed<ScopeTreeNode[]>(() => [{ key: 'project', type: 'project', label: projectName.value, children: systems.value.map(system => ({ key: 'system:' + system.id, type: 'system', id: system.id, label: system.short_name || system.name, children: directoryChildren(system.id) })) }])
function message(cause: any, fallback: string) { ElMessage.error(cause?.response?.data?.message || fallback) }
function restoreColumnPreferences() { try { const saved = JSON.parse(localStorage.getItem(columnKey.value) || '[]') as Column[]; if (saved.length) columns.value = saved.map(savedColumn => ({ ...allColumns.find(item => item.key === savedColumn.key), ...savedColumn })).filter(item => item.key) as Column[] } catch { columns.value = allColumns.map(item => ({ ...item })) } }
function saveColumnPreferences() { localStorage.setItem(columnKey.value, JSON.stringify(columns.value)) }
async function loadDictionaries() { if (!projectId.value) return; dictionaries.value = (await listTestDictionaries(domain.value, { projectId: projectId.value, page: 1, size: 100 })).data.data.records || []; await Promise.all(['func_type', 'change_status', 'importance', 'accounting_flag'].map(async code => { const dictionary = dictionaries.value.find(item => item.dictionary_code === code); options[code] = dictionary ? ((await listTestDictionaryOptions(domain.value, { projectId: projectId.value!, dictionaryId: dictionary.id, page: 1, size: 100 })).data.data.records || []) : [] })) }
async function load() { if (!projectId.value) return; loading.value = true; try { const response = await Promise.all([getTestScopeTree(domain.value, projectId.value), listTestScopes(domain.value, { projectId: projectId.value, page: page.value, size: 20, physicalSubsystemId: selectedSystem.value, directoryId: selectedDirectory.value, keyword: keyword.value || undefined, status: filters.status, functionType: filters.functionType, changeStatus: filters.changeStatus, importance: filters.importance, accountingFlag: filters.accountingFlag, coverage: filters.coverage || undefined, recycled: recycled.value, sortBy: sort.prop, sortOrder: sort.order })]); tree.value = response[0].data.data; rows.value = response[1].data.data.records || []; total.value = response[1].data.data.total || 0 } catch (cause) { message(cause, '测试范围加载失败') } finally { loading.value = false } }
function selectTree(node: ScopeTreeNode) { selectedSystem.value = node.type === 'system' ? node.id : node.type === 'directory' ? node.directory?.physical_subsystem_id : undefined; selectedDirectory.value = node.type === 'directory' ? node.id : undefined; page.value = 1; void load() }
function resetFilters() { keyword.value = ''; Object.assign(filters, { status: [], functionType: [], changeStatus: [], importance: [], accountingFlag: [], coverage: '' }); page.value = 1; void load() }
function openScope(item?: TestScope) { if (!item && !selectedSystem.value) { ElMessage.warning('请先在左侧选择所属系统或所属目录'); return }; editing.value = item; Object.keys(form).forEach(key => delete (form as any)[key]); Object.assign(form, item ? { ...item } : { physical_subsystem_id: selectedSystem.value, directory_id: selectedDirectory.value, function_type: 'ONLINE', change_status: 'NEW', importance: 'MEDIUM', accounting_flag: 'NO' }); drawer.value = true }
function openDirectory(item?: TestDirectory, child = false) { editingDirectory.value = item; Object.keys(directory).forEach(key => delete (directory as any)[key]); if (item) Object.assign(directory, child ? { physical_subsystem_id: item.physical_subsystem_id, parent_id: item.id, sort_no: 0 } : { ...item }); else Object.assign(directory, { physical_subsystem_id: selectedSystem.value, parent_id: selectedDirectory.value, sort_no: 0 }); directoryDialog.value = true }
async function submit() { if (!projectId.value || !form.physical_subsystem_id || !form.directory_id || !form.scope_name) { ElMessage.warning('请填写功能/用例/批处理名称，并选择所属目录'); return }; saving.value = true; try { let response = await saveTestScope(domain.value, projectId.value, { ...form }); if (response.data.data.confirmation_required) { const affected = response.data.data.affected_case_count || 0; await ElMessageBox.confirm('该范围下已有 ' + affected + ' 条案例，修改序号将自动同步更新关联案例的编号前缀，是否继续？缺陷编号和已生成快照不会修改。', '确认序号变更', { type: 'warning', confirmButtonText: '确认修改' }); response = await saveTestScope(domain.value, projectId.value, { ...form, confirm_code_sync: true } as any) } drawer.value = false; ElMessage.success(editing.value ? '范围已更新' : '范围已创建'); await load() } catch (cause: any) { if (cause !== 'cancel' && cause !== 'close') message(cause, '范围保存失败') } finally { saving.value = false } }
async function submitDirectory() { if (!projectId.value || !directory.physical_subsystem_id || !directory.directory_name) { ElMessage.warning('请填写目录并选择参测系统'); return }; try { await saveTestScopeDirectory(domain.value, projectId.value, directory); directoryDialog.value = false; ElMessage.success(editingDirectory.value ? '目录已更新' : '目录已创建'); await load() } catch (cause) { message(cause, '目录保存失败') } }
async function removeDirectory(item: TestDirectory) { if (!projectId.value) return; try { await ElMessageBox.confirm('删除“' + item.directory_name + '”后，其下范围会移交至上级目录，范围数据不会删除。确认继续？', '删除范围目录', { type: 'warning' }); await deleteTestScopeDirectory(domain.value, projectId.value, item.id, item.parent_id); if (selectedDirectory.value === item.id) selectedDirectory.value = item.parent_id; await load() } catch (cause: any) { if (cause !== 'cancel' && cause !== 'close') message(cause, '删除目录失败') } }
async function remove(item: TestScope) { if (!projectId.value) return; try { await ElMessageBox.confirm('删除范围“' + item.scope_name + '”后，' + (item.case_count || 0) + ' 条关联案例会随范围在列表中隐藏；30 天内可在回收站恢复。', '删除测试范围', { type: 'warning' }); await deleteTestScope(domain.value, projectId.value, item.id); ElMessage.success('已移入回收站'); await load() } catch (cause: any) { if (cause !== 'cancel' && cause !== 'close') message(cause, '删除失败') } }
async function restore(item: TestScope) { if (!projectId.value) return; try { await restoreTestScope(domain.value, projectId.value, item.id); ElMessage.success('范围及关联案例已恢复'); await load() } catch (cause: any) { const reason = cause?.response?.data?.message || ''; if (reason.includes('序号')) { try { const value = await ElMessageBox.prompt('原序号已被占用，请输入恢复后的序号。', '处理序号冲突', { inputValue: item.scope_code, inputPattern: /^[A-Za-z0-9_-]+-[0-9]{4,}$/, inputErrorMessage: '请输入“系统编码-流水号”格式的序号' }); await restoreTestScope(domain.value, projectId.value, item.id, value.value); ElMessage.success('范围已恢复'); await load() } catch (inner: any) { if (inner !== 'cancel' && inner !== 'close') message(inner, '恢复失败') } } else message(cause, '恢复失败') } }
async function invalid(item: TestScope) { if (!projectId.value) return; try { const invalidated = !item.invalidated; const result = invalidated ? await ElMessageBox.prompt('无效原因', '置无效', { inputPlaceholder: '请输入无效原因' }) : undefined; await setTestScopeInvalidated(domain.value, projectId.value, item.id, invalidated, result?.value || ''); await load() } catch (cause: any) { if (cause !== 'cancel' && cause !== 'close') message(cause, '状态更新失败') } }
function statusName(value?: string) { return ({ SUCCESS: '通过', FAILED: '失败', RUNNING: '执行中', INVALID: '无效', UNEXECUTED: '未执行' } as Record<string, string>)[value || ''] || '未执行' }
function statusType(value?: string) { return ({ SUCCESS: 'success', FAILED: 'danger', RUNNING: 'warning', INVALID: 'info', UNEXECUTED: 'info' } as Record<string, any>)[value || 'UNEXECUTED'] }
function sortChange(value: { prop: string; order: 'ascending' | 'descending' | null }) { sort.prop = value.prop || 'updated_at'; sort.order = value.order || 'descending'; void load() }
async function download(path: '/template' | '/export') { if (!projectId.value) return; try { await downloadTestScopeFile(domain.value, path, path === '/template' ? {} : { projectId: projectId.value, physicalSubsystemId: selectedSystem.value, directoryId: selectedDirectory.value, keyword: keyword.value || undefined, status: filters.status, functionType: filters.functionType, changeStatus: filters.changeStatus, importance: filters.importance, accountingFlag: filters.accountingFlag, coverage: filters.coverage || undefined }, path === '/template' ? '测试范围导入模板.xlsx' : '测试范围导出.xlsx') } catch (cause) { message(cause, '文件下载失败') } }
async function previewImport(file: File) { if (!projectId.value) return; importFile.value = file; importPreview.value = undefined; try { importPreview.value = (await previewTestScopeImport(domain.value, projectId.value, file)).data.data } catch (cause) { message(cause, '导入预校验失败') } }
function selectImport(file: { raw?: File }) { if (file.raw) void previewImport(file.raw) }
async function commitImport() { if (!projectId.value || !importFile.value || !importPreview.value?.success) return; saving.value = true; try { const result = (await importTestScopes(domain.value, projectId.value, importFile.value, duplicateAction.value)).data.data; importDialog.value = false; ElMessage.success('导入完成：新增 ' + (result.created || 0) + '，覆盖 ' + (result.updated || 0) + '，跳过 ' + (result.skipped || 0)); await load() } catch (cause) { message(cause, '导入提交失败') } finally { saving.value = false } }
onMounted(async () => { await context.initialize(); projects.value = (await listTestProjects(domain.value)).data.data || []; restoreColumnPreferences(); await Promise.all([load(), loadDictionaries()]) })
watch([() => context.currentRef, domain], async () => { page.value = 1; selectedSystem.value = undefined; selectedDirectory.value = undefined; restoreColumnPreferences(); await Promise.all([load(), loadDictionaries()]) })
</script>

<template>
  <section class="scope-page">
    <UiPageHeader eyebrow="测试管理" :title="(domain === 'application-assembly' ? '应用组装测试' : domain === 'user-testing' ? '用户测试' : domain === 'non-functional' ? '非功能测试' : '安全测试') + ' · 测试范围'"><template #actions><el-button v-if="can('create') && !recycled" type="primary" size="small" :icon="Plus" @click="openScope()">新建范围</el-button><el-dropdown v-if="!recycled" trigger="click"><el-button size="small"><el-icon><Upload /></el-icon> 导入</el-button><template #dropdown><el-dropdown-menu><el-dropdown-item @click="download('/template')">下载模板</el-dropdown-item><el-dropdown-item @click="importDialog = true">导入范围</el-dropdown-item><el-dropdown-item @click="download('/export')">导出当前结果</el-dropdown-item></el-dropdown-menu></template></el-dropdown><el-tooltip content="字段设置"><el-button size="small" text circle :icon="Setting" aria-label="字段设置" @click="columnsDialog = true" /></el-tooltip><el-tooltip content="刷新"><el-button size="small" text circle :icon="Refresh" aria-label="刷新范围" @click="load" /></el-tooltip></template></UiPageHeader>
    <UiEmptyState v-if="!projectId" title="请先选择项目" description="请使用顶部全局项目选择器后查看测试范围。" />
    <section v-else class="scope-workspace" v-loading="loading"><aside class="scope-tree"><header><span>范围目录</span><el-tooltip v-if="can('create') && !recycled" content="新建根目录"><el-button link :icon="Plus" aria-label="新建范围目录" @click="openDirectory()" /></el-tooltip></header><el-tree :data="treeData" node-key="key" :current-node-key="selectedTreeKey" default-expand-all highlight-current :expand-on-click-node="false" @node-click="selectTree"><template #default="{ data }"><span class="scope-tree-node"><el-icon><FolderOpened v-if="data.type === 'project'" /><Folder v-else /></el-icon><span class="scope-tree-label">{{ data.label }}</span><span v-if="data.type === 'directory' && !recycled && can('update')" class="tree-actions"><el-button link :icon="Plus" aria-label="新增子目录" @click.stop="openDirectory(data.directory, true)" /><el-button link :icon="Edit" aria-label="编辑目录" @click.stop="openDirectory(data.directory)" /><el-button v-if="can('delete')" link type="danger" :icon="Delete" aria-label="删除目录" @click.stop="removeDirectory(data.directory)" /></span></span></template></el-tree></aside>
      <main class="scope-content"><div class="scope-toolbar"><el-input v-model="keyword" clearable size="small" placeholder="序号、名称、末级菜单名称" @keyup.enter="load"><template #prefix><Search /></template></el-input><el-select v-model="filters.status" multiple collapse-tags size="small" clearable placeholder="状态"><el-option v-for="item in ['SUCCESS','FAILED','RUNNING','INVALID','UNEXECUTED']" :key="item" :label="statusName(item)" :value="item" /></el-select><el-select v-model="filters.functionType" multiple collapse-tags size="small" clearable placeholder="功能类型"><el-option v-for="item in dictionaryOptions('func_type')" :key="item.id" :label="item.option_name" :value="item.option_code" /></el-select><el-select v-model="filters.changeStatus" multiple collapse-tags size="small" clearable placeholder="变动状态"><el-option v-for="item in dictionaryOptions('change_status')" :key="item.id" :label="item.option_name" :value="item.option_code" /></el-select><el-select v-model="filters.importance" multiple collapse-tags size="small" clearable placeholder="业务重要程度"><el-option v-for="item in dictionaryOptions('importance')" :key="item.id" :label="item.option_name" :value="item.option_code" /></el-select><el-select v-model="filters.accountingFlag" multiple collapse-tags size="small" clearable placeholder="是否核算相关"><el-option v-for="item in dictionaryOptions('accounting_flag')" :key="item.id" :label="item.option_name" :value="item.option_code" /></el-select><el-select v-model="filters.coverage" size="small" clearable placeholder="有无案例覆盖"><el-option label="有案例" value="COVERED" /><el-option label="无案例" value="UNCOVERED" /></el-select><el-button size="small" :icon="Search" @click="page = 1; load()">查询</el-button><el-button size="small" text @click="resetFilters">重置</el-button></div><div class="scope-result-bar"><span>{{ recycled ? '回收站 · 删除后 30 天内可恢复' : '范围状态实时派生；当前执行模块未接入时显示未执行。' }}</span><el-button size="small" text :icon="Box" @click="recycled = !recycled; page = 1; load()">{{ recycled ? '返回范围列表' : '回收站' }}</el-button></div>
        <UiDataTable :data="rows" :loading="loading" row-key="id" border class="scope-table" @sort-change="sortChange"><el-table-column v-for="column in activeColumns" :key="column.key" :label="column.label" :prop="column.prop as string" :width="column.width" :min-width="column.minWidth" :sortable="column.key === 'status' ? false : 'custom'" show-overflow-tooltip resizable><template v-if="column.key === 'status'" #default="{ row }"><el-tag :type="statusType(row.status)" size="small">{{ statusName(row.status) }}</el-tag></template><template v-else-if="column.key === 'case_count'" #default="{ row }"><el-button link type="primary" :disabled="!row.case_count" @click="$router.push({ path: '/test-management/' + domain + '/cases', query: { scopeId: row.id } })">{{ row.case_count || 0 }}</el-button></template><template v-else-if="column.key === 'created_at' || column.key === 'updated_at'" #default="{ row }">{{ row[column.prop as keyof TestScope] ? String(row[column.prop as keyof TestScope]).slice(5, 16).replace('T', ' ') : '-' }}</template></el-table-column><el-table-column label="操作" width="96" fixed="right" align="center" header-align="center" :resizable="false"><template #default="{ row }"><div class="scope-actions"><template v-if="recycled"><el-tooltip content="恢复"><el-button link type="primary" aria-label="恢复范围" @click="restore(row)"><el-icon><CircleCheck /></el-icon></el-button></el-tooltip></template><template v-else><el-tooltip v-if="can('update')" content="编辑"><el-button link :icon="Edit" aria-label="编辑范围" @click="openScope(row)" /></el-tooltip><el-tooltip v-if="can('update')" :content="row.invalidated ? '撤销无效' : '置无效'"><el-button link aria-label="切换范围有效状态" @click="invalid(row)"><el-icon><CircleClose /></el-icon></el-button></el-tooltip><el-tooltip v-if="can('delete')" content="删除"><el-button link type="danger" :icon="Delete" aria-label="删除范围" @click="remove(row)" /></el-tooltip></template></div></template></el-table-column><template #footer><el-pagination v-model:current-page="page" :total="total" :page-size="20" layout="total, prev, pager, next" @current-change="load" /></template></UiDataTable></main></section>
    <TestManagementFormDialog v-model="drawer" :title="editing ? '编辑测试范围' : '新建测试范围'" width="min(640px, calc(100vw - 24px))" :loading="saving" @submit="submit"><el-form label-width="118px"><el-form-item label="序号"><el-input v-model="form.scope_code" placeholder="留空自动生成，如 W10011-0001" /></el-form-item><el-form-item label="功能/用例/批处理名称" required><el-input v-model="form.scope_name" maxlength="100" show-word-limit /></el-form-item><el-form-item label="末级菜单名称"><el-input v-model="form.leaf_menu" maxlength="200" /></el-form-item><el-form-item label="所属系统"><el-input :model-value="formSystemName" disabled /></el-form-item><el-form-item label="所属目录" required><el-select v-model="form.directory_id" style="width:100%"><el-option v-for="item in directories.filter(d => d.physical_subsystem_id === form.physical_subsystem_id)" :key="item.id" :label="item.directory_name" :value="item.id" /></el-select></el-form-item><el-form-item label="功能类型" required><el-select v-model="form.function_type" style="width:100%"><el-option v-for="item in dictionaryOptions('func_type')" :key="item.id" :label="item.option_name" :value="item.option_code" /></el-select></el-form-item><el-form-item label="变动状态" required><el-select v-model="form.change_status" style="width:100%"><el-option v-for="item in dictionaryOptions('change_status')" :key="item.id" :label="item.option_name" :value="item.option_code" /></el-select></el-form-item><el-form-item label="业务重要程度" required><el-select v-model="form.importance" style="width:100%"><el-option v-for="item in dictionaryOptions('importance')" :key="item.id" :label="item.option_name" :value="item.option_code" /></el-select></el-form-item><el-form-item label="是否核算相关" required><el-select v-model="form.accounting_flag" style="width:100%"><el-option v-for="item in dictionaryOptions('accounting_flag')" :key="item.id" :label="item.option_name" :value="item.option_code" /></el-select></el-form-item></el-form></TestManagementFormDialog>
    <el-dialog v-model="directoryDialog" :title="editingDirectory ? '编辑范围目录' : '新建范围目录'" width="min(460px, calc(100vw - 24px))"><el-form label-width="84px"><el-form-item label="参测系统" required><el-select v-model="directory.physical_subsystem_id" style="width:100%" :disabled="Boolean(editingDirectory)"><el-option v-for="item in systems" :key="item.id" :label="item.short_name || item.name" :value="item.id" /></el-select></el-form-item><el-form-item label="上级目录"><el-select v-model="directory.parent_id" clearable style="width:100%"><el-option v-for="item in directories.filter(d => d.physical_subsystem_id === directory.physical_subsystem_id && d.id !== directory.id)" :key="item.id" :label="item.directory_name" :value="item.id" /></el-select></el-form-item><el-form-item label="目录名称" required><el-input v-model="directory.directory_name" maxlength="100" /></el-form-item><el-form-item label="排序"><el-input-number v-model="directory.sort_no" :min="0" /></el-form-item></el-form><template #footer><el-button @click="directoryDialog = false">取消</el-button><el-button type="primary" @click="submitDirectory">保存</el-button></template></el-dialog>
    <el-dialog v-model="columnsDialog" title="字段设置" width="min(440px, calc(100vw - 24px))"><p class="dialog-tip">勾选显示字段；列宽可直接在列表拖动调整，设置按当前用户、项目和测试大类保存。</p><div class="column-settings"><el-checkbox v-for="column in columns" :key="column.key" v-model="column.visible">{{ column.label }}</el-checkbox></div><template #footer><el-button @click="columns = allColumns.map(item => ({ ...item }))">恢复默认</el-button><el-button @click="columnsDialog = false">取消</el-button><el-button type="primary" @click="saveColumnPreferences(); columnsDialog = false">保存设置</el-button></template></el-dialog>
    <el-dialog v-model="importDialog" title="批量导入测试范围" width="min(720px, calc(100vw - 24px))" destroy-on-close><el-alert title="支持 XLSX，单文件不超过 50MB。先预校验；只要存在失败行，提交按钮不可用。" type="info" :closable="false" show-icon /><el-upload class="scope-import-upload" drag :auto-upload="false" accept=".xlsx" :limit="1" :on-change="selectImport" :on-remove="() => { importFile = undefined; importPreview = undefined }"><el-icon class="el-icon--upload"><Upload /></el-icon><div class="el-upload__text">拖入 XLSX 文件，或 <em>点击选择</em></div></el-upload><template v-if="importPreview"><div class="import-summary"><span>总计 {{ importPreview.total }}</span><span>通过 {{ importPreview.valid }}</span><span>失败 {{ importPreview.failed }}</span><span>重复 {{ importPreview.duplicate }}</span><span>待建目录 {{ importPreview.directories }}</span></div><el-radio-group v-if="importPreview.duplicate" v-model="duplicateAction"><el-radio value="SKIP">重复编码跳过</el-radio><el-radio value="OVERWRITE">重复编码覆盖非空字段</el-radio></el-radio-group><el-table v-if="importPreview.errors.length" :data="importPreview.errors" max-height="180" size="small"><el-table-column prop="row_number" label="行号" width="80" /><el-table-column prop="message" label="错误说明" /></el-table></template><template #footer><el-button @click="importDialog = false">取消</el-button><el-button type="primary" :disabled="!importPreview?.success" :loading="saving" @click="commitImport">确认导入</el-button></template></el-dialog>
  </section>
</template>

